231→// sessionShutdownData is the data payload for session.shutdown events.
232→// Contains aggregate model metrics for the entire session.
233→type sessionShutdownData struct {
234→	ModelMetrics []modelMetric `json:"modelMetrics"`
235→}
236→
237→// modelMetric contains per-model token usage aggregates.
238→type modelMetric struct {
239→	ModelID  string        `json:"modelId"`
240→	Requests modelRequests `json:"requests"`
241→	Usage    modelUsage    `json:"usage"`
242→}
243→
244→type modelRequests struct {
245→	Count int `json:"count"`
246→}
247→
248→type modelUsage struct {
249→	InputTokens      int `json:"inputTokens"`
250→	OutputTokens     int `json:"outputTokens"`
251→	CacheReadTokens  int `json:"cacheReadTokens"`
252→	CacheWriteTokens int `json:"cacheWriteTokens"`
253→}
254→
255→// assistantMessageTokenData is used as a fallback when session.shutdown is not
256→// yet available. Each assistant.message may carry an outputTokens field.
257→type assistantMessageTokenData struct {
258→	OutputTokens int `json:"outputTokens"`
259→}
260→
261→const eventTypeSessionShutdown = "session.shutdown"
262→
263→// CalculateTokenUsage computes token usage from the Copilot CLI JSONL transcript.
264→// It prefers session.shutdown events (which contain session-wide aggregates) and
265→// falls back to summing per-message outputTokens from assistant.message events.
266→func (c *CopilotCLIAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
267→	events, err := parseEventsFromOffset(transcriptData, fromOffset)
268→	if err != nil {
269→		return nil, fmt.Errorf("failed to parse transcript for token usage: %w", err)
270→	}
271→
272→	return extractTokenUsageFromEvents(events), nil
273→}
274→
275→// extractTokenUsageFromEvents extracts token usage from parsed events.
276→// Prefers session.shutdown aggregate; falls back to per-message outputTokens.
277→func extractTokenUsageFromEvents(events []copilotEvent) *agent.TokenUsage {
278→	// Try session.shutdown first — authoritative session-wide aggregate
279→	for i := len(events) - 1; i >= 0; i-- {
280→		if events[i].Type != eventTypeSessionShutdown {
281→			continue
282→		}
283→
284→		var data sessionShutdownData
285→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
286→			continue
287→		}
288→
289→		if len(data.ModelMetrics) == 0 {
290→			continue
291→		}
292→
293→		// Sum across all models
294→		usage := &agent.TokenUsage{}
295→		for _, m := range data.ModelMetrics {
296→			usage.InputTokens += m.Usage.InputTokens
297→			usage.OutputTokens += m.Usage.OutputTokens
298→			usage.CacheReadTokens += m.Usage.CacheReadTokens
299→			usage.CacheCreationTokens += m.Usage.CacheWriteTokens
300→			usage.APICallCount += m.Requests.Count
301→		}
302→		return usage
303→	}
304→
305→	// Fallback: sum outputTokens from assistant.message events
306→	usage := &agent.TokenUsage{}
307→	for i := range events {
308→		if events[i].Type != eventTypeAssistantMsg {
309→			continue
310→		}
311→
312→		var data assistantMessageTokenData
313→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
314→			continue
315→		}
316→		usage.OutputTokens += data.OutputTokens
317→		if data.OutputTokens > 0 {
318→			usage.APICallCount++
319→		}
320→	}
321→
322→	return usage
323→}
