325→// ExtractModelFromTranscript extracts the LLM model name from a Copilot CLI
326→// transcript. It prefers session.model_change events (explicit model
327→// declarations), but falls back to the model field on tool.execution_complete
328→// events for Copilot CLI versions that do not emit session.model_change.
329→// Returns the last observed model, or empty string if unavailable.
330→func ExtractModelFromTranscript(ctx context.Context, transcriptPath string) string {
331→	if transcriptPath == "" {
332→		return ""
333→	}
334→
335→	data, err := os.ReadFile(transcriptPath) //nolint:gosec // Path derived from agent hook input
336→	if err != nil {
337→		logging.Debug(ctx, "copilot-cli: failed to read transcript for model extraction",
338→			"transcriptPath", transcriptPath, "err", err)
339→		return ""
340→	}
341→
342→	events, err := parseEventsFromBytes(data)
343→	if err != nil {
344→		logging.Debug(ctx, "copilot-cli: failed to parse transcript for model extraction",
345→			"transcriptPath", transcriptPath, "err", err)
346→		return ""
347→	}
348→
349→	model := extractModelFromEvents(events)
350→	if model == "" {
351→		logging.Debug(ctx, "copilot-cli: no model found in transcript",
352→			"transcriptPath", transcriptPath, "eventCount", len(events))
353→	}
354→
355→	return model
356→}
