358→// GetTranscriptPosition returns the current line count of a Copilot CLI transcript.
359→// Copilot CLI uses JSONL format, so position is the number of lines.
360→// This is a lightweight operation that only counts lines without parsing JSON.
361→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
362→// Returns 0 if the file doesn't exist or is empty.
363→func (c *CopilotCLIAgent) GetTranscriptPosition(path string) (int, error) {
364→	if path == "" {
365→		return 0, nil
366→	}
367→
368→	file, err := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
369→	if err != nil {
370→		if os.IsNotExist(err) {
371→			return 0, nil
372→		}
373→		return 0, fmt.Errorf("failed to open transcript file: %w", err)
374→	}
375→	defer file.Close()
376→
377→	reader := bufio.NewReader(file)
378→	lineCount := 0
379→
380→	for {
381→		line, readErr := reader.ReadBytes('\n')
382→		if readErr != nil {
383→			if readErr == io.EOF {
384→				if len(line) > 0 {
385→					lineCount++ // Count final line without trailing newline
386→				}
387→				break
388→			}
389→			return 0, fmt.Errorf("failed to read transcript: %w", readErr)
390→		}
391→		lineCount++
392→	}
393→
394→	return lineCount, nil
395→}
396→
397→// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
398→// For Copilot CLI (JSONL format), offset is the starting line number.
399→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
400→// Returns:
401→//   - files: list of file paths modified by Copilot (from tool.execution_complete events)
402→//   - currentPosition: total number of lines in the file
403→//   - error: any error encountered during reading
404→func (c *CopilotCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
405→	if path == "" {
406→		return nil, 0, nil
407→	}
408→
409→	file, openErr := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
410→	if openErr != nil {
411→		return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
412→	}
413→	defer file.Close()
414→
415→	reader := bufio.NewReader(file)
416→	var events []copilotEvent
417→	lineNum := 0
418→
419→	for {
420→		lineData, readErr := reader.ReadBytes('\n')
421→		if readErr != nil && readErr != io.EOF {
422→			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
423→		}
424→
425→		if len(lineData) > 0 {
426→			lineNum++
427→			if lineNum > startOffset {
428→				var ev copilotEvent
429→				if parseErr := json.Unmarshal(lineData, &ev); parseErr == nil {
430→					events = append(events, ev)
431→				}
432→				// Skip malformed lines silently
433→			}
434→		}
435→
436→		if readErr == io.EOF {
437→			break
438→		}
439→	}
440→
441→	return extractModifiedFilesFromEvents(events), lineNum, nil
442→}
443→
444→// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
445→func (c *CopilotCLIAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
446→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
447→	if err != nil {
448→		return nil, fmt.Errorf("failed to read transcript: %w", err)
449→	}
450→
451→	events, err := parseEventsFromOffset(data, fromOffset)
452→	if err != nil {
453→		return nil, fmt.Errorf("failed to parse transcript events: %w", err)
454→	}
455→	return extractPromptsFromEvents(events), nil
456→}
457→
458→// ExtractSummary extracts the last assistant message as a session summary.
459→func (c *CopilotCLIAgent) ExtractSummary(sessionRef string) (string, error) {
460→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
461→	if err != nil {
462→		return "", fmt.Errorf("failed to read transcript: %w", err)
463→	}
464→
465→	events, err := parseEventsFromBytes(data)
466→	if err != nil {
467→		return "", fmt.Errorf("failed to parse transcript events: %w", err)
468→	}
469→	return extractSummaryFromEvents(events), nil
470→}
