452→func gitCommit(dir string, files []string) {
453→	if len(files) == 0 {
454→		gitRun(dir, "add", ".")
455→	} else {
456→		gitRun(dir, append([]string{"add", "--"}, files...)...)
457→	}
458→	gitRun(dir, "commit", "-m", "Vogon agent commit")
459→}
