14→func init() {
15→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "vogon" {
16→		return
17→	}
18→	// Only register if the binary exists (built by the test runner).
19→	if _, err := exec.LookPath("vogon"); err != nil {
20→		return
21→	}
22→	Register(&Vogon{})
23→}
