469→// PatchSettings merges extra keys into .entire/settings.json.
470→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
471→	t.Helper()
472→	path := filepath.Join(dir, ".entire", "settings.json")
473→	data, err := os.ReadFile(path)
474→	if err != nil {
475→		t.Fatalf("read settings: %v", err)
476→	}
477→	var settings map[string]any
478→	if err := json.Unmarshal(data, &settings); err != nil {
479→		t.Fatalf("parse settings: %v", err)
480→	}
481→	for k, v := range extra {
