484→	out, err := json.MarshalIndent(settings, "", "  ")
485→	if err != nil {
486→		t.Fatalf("marshal settings: %v", err)
487→	}
488→	if err := os.WriteFile(path, out, 0o644); err != nil {
489→		t.Fatalf("write settings: %v", err)
490→	}
