545→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
546→// checkpoint branch. It parses the two-level directory structure
547→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
548→func CheckpointIDs(t *testing.T, dir string) []string {
549→	t.Helper()
