241→// WaitForSessionIdle polls the session state files in .git/entire-sessions/
242→// until no session has phase "active", or fails the test after timeout.
243→// This handles the race where an agent's prompt pattern appears in the TUI
244→// before the turn-end hook has completed (transitioning ACTIVE → IDLE).
245→func WaitForSessionIdle(t *testing.T, dir string, timeout time.Duration) {
246→	t.Helper()
247→	stateDir := filepath.Join(dir, ".git", "entire-sessions")
248→	deadline := time.Now().Add(timeout)
249→	for time.Now().Before(deadline) {
250→		entries, err := os.ReadDir(stateDir)
251→		if err != nil {
252→			// Directory may not exist yet; keep polling
253→			time.Sleep(200 * time.Millisecond)
254→			continue
255→		}
256→		anyActive := false
257→		for _, entry := range entries {
258→			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") || strings.HasSuffix(entry.Name(), ".tmp") {
259→				continue
260→			}
261→			data, err := os.ReadFile(filepath.Join(stateDir, entry.Name()))
262→			if err != nil {
263→				continue
264→			}
265→			var state struct {
266→				Phase string `json:"phase"`
267→			}
268→			if err := json.Unmarshal(data, &state); err != nil {
269→				continue
270→			}
271→			if state.Phase == "active" {
272→				anyActive = true
273→				break
274→			}
275→		}
276→		if !anyActive {
277→			return
278→		}
279→		time.Sleep(200 * time.Millisecond)
280→	}
281→	t.Fatalf("session(s) did not transition to idle within %s", timeout)
282→}
