321→// ValidateCheckpointDeep performs comprehensive validation of checkpoint metadata
322→// on the checkpoint branch, including transcript JSONL validity, content hash
323→// verification, and prompt content checking.
324→func ValidateCheckpointDeep(t *testing.T, dir string, v DeepCheckpointValidation) {
325→	t.Helper()
326→
327→	// Basic metadata validation
328→	AssertCheckpointExists(t, dir, v.CheckpointID)
329→	AssertCheckpointMetadataComplete(t, dir, v.CheckpointID)
330→
331→	if v.Strategy != "" {
332→		meta := ReadCheckpointMetadata(t, dir, v.CheckpointID)
333→		assert.Equal(t, v.Strategy, meta.Strategy,
334→			"checkpoint %s: strategy mismatch", v.CheckpointID)
335→	}
336→
337→	if len(v.FilesTouched) > 0 {
338→		AssertCheckpointFilesTouched(t, dir, v.CheckpointID, v.FilesTouched)
339→	}
340→
341→	path := CheckpointPath(v.CheckpointID)
342→
343→	// Validate session metadata exists and has checkpoint_id
344→	sessionBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/metadata.json", path)
345→	sessionRaw := gitOutputSafe(dir, "show", sessionBlob)
346→	if assert.NotEmpty(t, sessionRaw, "session metadata should exist at %s", sessionBlob) {
347→		var sessionMeta map[string]any
348→		if assert.NoError(t, json.Unmarshal([]byte(sessionRaw), &sessionMeta)) {
349→			assert.Equal(t, v.CheckpointID, sessionMeta["checkpoint_id"],
350→				"session metadata checkpoint_id should match")
351→			assert.NotEmpty(t, sessionMeta["created_at"], "session metadata should have created_at")
352→		}
353→	}
354→
355→	// Validate transcript is valid JSONL
356→	transcriptBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/full.jsonl", path)
357→	transcriptRaw := gitOutputSafe(dir, "show", transcriptBlob)
358→	if assert.NotEmpty(t, transcriptRaw, "transcript should exist at %s", transcriptBlob) {
359→		lines := strings.Split(transcriptRaw, "\n")
360→		nonEmpty := 0
361→		for _, line := range lines {
362→			if strings.TrimSpace(line) != "" {
363→				nonEmpty++
364→			}
365→		}
366→		assert.Positive(t, nonEmpty, "transcript should have at least one line")
